<?php

namespace Tests\Feature;

use App\Models\UpdateClient;
use App\Models\UpdateDeploymentTarget;
use App\Models\UpdateRelease;
use App\Models\User;
use App\Services\Update\UpdateLifecycle;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;

/**
 * Central update management and the device API. Signatures here are real Ed25519 over a real manifest; only the key is
 * a throw-away one generated by the test.
 */
class UpdateServiceTest extends TestCase
{
    use DatabaseTransactions;

    private string $secret;
    private string $store;
    private string $version;

    protected function setUp(): void
    {
        parent::setUp();
        if (!function_exists('sodium_crypto_sign_keypair')) {
            $this->markTestSkipped('sodium is required on the update service');
        }
        $pair = sodium_crypto_sign_keypair();
        $this->secret = sodium_crypto_sign_secretkey($pair);
        $this->store = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'fc-upd-' . bin2hex(random_bytes(4));
        $this->version = '90.' . random_int(1, 9000) . '.0';
        config([
            'foodcourt.embedded' => false,
            'foodcourt.updates.service' => true,
            'foodcourt.updates.trusted_keys' => 'k1:' . base64_encode(sodium_crypto_sign_publickey($pair)),
            'foodcourt.updates.storage_path' => $this->store,
        ]);
    }

    protected function tearDown(): void
    {
        if (is_dir($this->store)) {
            array_map('unlink', glob($this->store . '/*') ?: []);
            rmdir($this->store);
        }
        parent::tearDown();
    }

    private function owner(): User
    {
        return User::factory()->create(['role' => 'owner', 'is_active' => true, 'email' => 'upd-owner-' . bin2hex(random_bytes(4)) . '@example.com']);
    }

    private function manifest(array $over = []): array
    {
        $payload = $over['_payload'] ?? 'payload-bytes';
        unset($over['_payload']);
        $manifest = [
            'format' => 1,
            'release_id' => 'rel-' . $this->version,
            'version' => $this->version,
            'source_version' => null,
            'package_type' => 'full',
            'channel' => 'stable',
            'payload_sha256' => hash('sha256', $payload),
            'payload_size' => strlen($payload),
            'tree' => [],
            'notes' => ['features' => ['A thing']],
            'compatibility' => ['electron_major' => 44],
            'database' => ['engine' => 'sqlite', 'schema_fingerprint' => str_repeat('a', 64), 'schema' => [], 'migrations' => []],
            ...$over,
        ];

        return [json_encode($manifest), $payload];
    }

    /** Creates a release, adds a package and uploads its payload. */
    private function releaseWithPackage(User $owner, array $manifestOver = [], array $releaseOver = []): array
    {
        $release = $this->actingAs($owner)->postJson('/api/update-admin/releases', ['version' => $this->version, 'channel' => 'stable', ...$releaseOver])->assertCreated()->json('data');
        $packageId = $this->addPackage($owner, $release['id'], $manifestOver);

        return [$release, $packageId];
    }

    private function addPackage(User $owner, int $releaseId, array $manifestOver = []): int
    {
        [$raw] = $this->manifest($manifestOver);
        $packageId = $this->actingAs($owner)->postJson("/api/update-admin/releases/{$releaseId}/packages", [
            'manifest' => $raw,
            'signature' => base64_encode(sodium_crypto_sign_detached($raw, $this->secret)),
            'signing_key_id' => 'k1',
        ])->assertCreated()->json('data.package_id');

        return $packageId;
    }

    /** php://input is not available to the in-process test client, so the stored file is written the way the endpoint would. */
    private function storePayload(int $packageId, string $payload = 'payload-bytes'): void
    {
        $package = \App\Models\UpdatePackage::findOrFail($packageId);
        @mkdir($this->store, 0700, true);
        $name = "pkg-{$package->id}-{$package->package_sha256}.fcpkg";
        file_put_contents($this->store . DIRECTORY_SEPARATOR . $name, $payload);
        $package->forceFill(['storage_name' => $name, 'uploaded_at' => now()])->save();
    }

    private function enroll(User $owner, string $channel = 'stable', string $version = '1.0.0'): array
    {
        $code = $this->actingAs($owner)->postJson('/api/update-admin/enrollment-codes', ['channel' => $channel, 'customer_label' => 'Test court'])->assertCreated()->json('data.code');
        $device = 'device-' . bin2hex(random_bytes(8));
        $this->app['auth']->forgetGuards();
        $data = $this->postJson('/api/updates/client/enroll', ['code' => $code, 'device_id' => $device, 'name' => 'Counter 1', 'app_version' => $version])->assertCreated()->json('data');

        return ['id' => $data['client_id'], 'device' => $device, 'token' => $data['token'], 'headers' => ['Authorization' => 'Bearer ' . $data['token'], 'X-Update-Device' => $device]];
    }

    private function publishedAndDeployed(User $owner, array $client): array
    {
        [$release, $packageId] = $this->releaseWithPackage($owner);
        $this->storePayload($packageId);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertOk();
        $this->actingAs($owner)->postJson('/api/update-admin/deployments', ['release_id' => $release['id'], 'scope' => 'selected', 'client_ids' => [$client['id']]])->assertCreated();
        $this->app['auth']->forgetGuards();

        return [$release, $packageId];
    }

    private function check(array $client, string $version = '1.0.0')
    {
        return $this->withHeaders($client['headers'])->postJson('/api/updates/client/check', ['app_version' => $version, 'mode' => 'embedded']);
    }

    private function reportStatus(array $client, int $targetId, string $status, array $extra = [])
    {
        return $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$targetId}/status", ['status' => $status, ...$extra]);
    }

    /** Walks a device through to HEALTH_CHECK using the real endpoints. */
    private function walkToHealthCheck(array $client): int
    {
        $targetId = $this->check($client)->assertOk()->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$targetId}/decision", ['decision' => 'approve'])->assertOk();
        $token = $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$targetId}/download-token")->assertOk()->json('data.token');
        $this->reportStatus($client, $targetId, 'DOWNLOADING')->assertOk();
        $this->withHeaders($client['headers'])->get("/api/updates/client/download/{$token}")->assertOk();
        foreach (['VERIFYING', 'BACKUP_IN_PROGRESS', 'MIGRATING', 'INSTALLING', 'HEALTH_CHECK'] as $s) {
            $this->reportStatus($client, $targetId, $s)->assertOk();
        }

        return $targetId;
    }

    private function completion(array $client, int $targetId, array $over = []): array
    {
        $target = UpdateDeploymentTarget::with(['release', 'package'])->findOrFail($targetId);
        $fingerprint = $over['schema_fingerprint'] ?? str_repeat('a', 64);
        $manifest = $over['manifest_sha256'] ?? $target->package->manifest_sha256;

        return [
            'app_version' => $target->release->version,
            'manifest_sha256' => $manifest,
            'schema_fingerprint' => $fingerprint,
            'health' => ['startup' => true, 'database' => true, 'migrations_current' => true, 'schema_compatible' => true],
            'proof' => UpdateLifecycle::proof(UpdateClient::hashToken($client['token']), $target, $manifest, $fingerprint),
            ...$over,
        ];
    }

    // ------------------------------------------------------------------ boundaries
    public function test_all_update_routes_are_404_unless_this_deployment_is_the_service(): void
    {
        $owner = $this->owner();
        config(['foodcourt.updates.service' => false]);
        $this->actingAs($owner)->getJson('/api/update-admin/releases')->assertNotFound();
        $this->postJson('/api/updates/client/enroll', [])->assertNotFound();
        $this->postJson('/api/updates/client/check', [])->assertNotFound();
    }

    public function test_a_built_in_server_can_never_be_the_service(): void
    {
        config(['foodcourt.updates.service' => true, 'foodcourt.embedded' => true]);
        $this->actingAs($this->owner())->getJson('/api/update-admin/releases')->assertNotFound();
    }

    public function test_only_the_owner_manages_releases(): void
    {
        $cashier = User::factory()->create(['role' => 'cashier', 'is_active' => true, 'email' => 'upd-cash-' . bin2hex(random_bytes(4)) . '@example.com']);
        $this->actingAs($cashier)->getJson('/api/update-admin/releases')->assertForbidden();
        $this->actingAs($cashier)->postJson('/api/update-admin/releases', ['version' => $this->version, 'channel' => 'stable'])->assertForbidden();
    }

    public function test_the_admin_api_requires_sign_in(): void
    {
        $this->getJson('/api/update-admin/clients')->assertUnauthorized();
    }

    // ------------------------------------------------------------------ releases
    public function test_release_create_edit_publish_unpublish(): void
    {
        $owner = $this->owner();
        [$release, $packageId] = $this->releaseWithPackage($owner, [], ['required' => false]);
        $this->assertSame('RELEASE_CREATED', $release['status']);
        $this->actingAs($owner)->putJson("/api/update-admin/releases/{$release['id']}", ['min_supported_version' => '1.0.0', 'notes' => ['bug_fixes' => ['x']]])->assertOk();

        $this->storePayload($packageId);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertOk()->assertJsonPath('data.status', 'RELEASE_PUBLISHED');
        $this->actingAs($owner)->putJson("/api/update-admin/releases/{$release['id']}", ['channel' => 'beta'])->assertStatus(409);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/unpublish")->assertOk()->assertJsonPath('data.status', 'RELEASE_CREATED');
    }

    public function test_a_release_without_a_verified_full_package_cannot_be_published(): void
    {
        $owner = $this->owner();
        $release = $this->actingAs($owner)->postJson('/api/update-admin/releases', ['version' => $this->version, 'channel' => 'stable'])->assertCreated()->json('data');
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertStatus(409)->assertJsonPath('code', 'no_full_package');

        $this->addPackage($owner, $release['id']); // manifest accepted, payload never stored
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertStatus(409);
    }

    public function test_bad_signatures_and_mismatched_manifests_are_refused(): void
    {
        $owner = $this->owner();
        $release = $this->actingAs($owner)->postJson('/api/update-admin/releases', ['version' => $this->version, 'channel' => 'stable'])->json('data');
        [$raw] = $this->manifest();
        $sig = base64_encode(sodium_crypto_sign_detached($raw, $this->secret));
        $url = "/api/update-admin/releases/{$release['id']}/packages";

        $this->actingAs($owner)->postJson($url, ['manifest' => str_replace('"format":1', '"format":1,"x":1', $raw), 'signature' => $sig, 'signing_key_id' => 'k1'])->assertStatus(422)->assertJsonPath('code', 'manifest_rejected');
        $this->actingAs($owner)->postJson($url, ['manifest' => $raw, 'signature' => $sig, 'signing_key_id' => 'unknown'])->assertStatus(422);
        $this->actingAs($owner)->postJson($url, ['manifest' => $raw, 'signature' => 'not-base64!', 'signing_key_id' => 'k1'])->assertStatus(422);

        [$other] = $this->manifest(['version' => '99.99.99']);
        $this->actingAs($owner)->postJson($url, ['manifest' => $other, 'signature' => base64_encode(sodium_crypto_sign_detached($other, $this->secret)), 'signing_key_id' => 'k1'])->assertStatus(422);
    }

    public function test_an_older_release_cannot_be_published_over_a_newer_one(): void
    {
        $owner = $this->owner();
        [$release, $packageId] = $this->releaseWithPackage($owner);
        $this->storePayload($packageId);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertOk();

        $newest = $this->version;
        $this->version = '80.0.' . random_int(1, 99999);
        [$older, $olderPackage] = $this->releaseWithPackage($owner);
        $this->storePayload($olderPackage);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$older['id']}/publish")->assertStatus(409)->assertJsonPath('code', 'downgrade');
        $this->assertTrue(version_compare($newest, $this->version, '>'));
    }

    public function test_deployment_needs_a_published_release(): void
    {
        $owner = $this->owner();
        [$release] = $this->releaseWithPackage($owner);
        $this->actingAs($owner)->postJson('/api/update-admin/deployments', ['release_id' => $release['id'], 'scope' => 'all'])->assertStatus(409);
    }

    // ------------------------------------------------------------------ clients
    public function test_enrollment_code_works_once_and_only_a_hash_is_stored(): void
    {
        $owner = $this->owner();
        $code = $this->actingAs($owner)->postJson('/api/update-admin/enrollment-codes')->json('data.code');
        $this->assertDatabaseMissing('update_enrollment_codes', ['code_hash' => $code]);
        $this->app['auth']->forgetGuards();

        $body = ['code' => $code, 'device_id' => 'device-' . bin2hex(random_bytes(8)), 'name' => 'PC'];
        $token = $this->postJson('/api/updates/client/enroll', $body)->assertCreated()->json('data.token');
        $this->assertDatabaseHas('update_clients', ['device_id' => $body['device_id'], 'token_hash' => hash('sha256', $token)]);
        $this->postJson('/api/updates/client/enroll', [...$body, 'device_id' => 'device-' . bin2hex(random_bytes(8))])->assertStatus(422);
    }

    public function test_expired_codes_are_refused(): void
    {
        $owner = $this->owner();
        $code = $this->actingAs($owner)->postJson('/api/update-admin/enrollment-codes')->json('data.code');
        \App\Models\UpdateEnrollmentCode::query()->where('code_hash', hash('sha256', $code))->update(['expires_at' => now()->subMinute()]);
        $this->postJson('/api/updates/client/enroll', ['code' => $code, 'device_id' => 'device-' . bin2hex(random_bytes(8)), 'name' => 'PC'])->assertStatus(422);
    }

    public function test_device_is_validated_on_every_operation(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->postJson('/api/updates/client/check', ['app_version' => '1.0.0'])->assertUnauthorized();
        $this->withHeaders(['Authorization' => 'Bearer wrong', 'X-Update-Device' => $client['device']])->postJson('/api/updates/client/check', ['app_version' => '1.0.0'])->assertUnauthorized();
        $this->withHeaders([...$client['headers'], 'X-Update-Device' => 'other-device-id-000'])->postJson('/api/updates/client/check', ['app_version' => '1.0.0'])->assertUnauthorized();
        $this->check($client)->assertOk();

        UpdateClient::findOrFail($client['id'])->update(['status' => 'suspended']);
        $this->check($client)->assertForbidden()->assertJsonPath('code', 'device_not_authorized');
        UpdateClient::findOrFail($client['id'])->update(['status' => 'revoked']);
        $this->check($client)->assertForbidden();
    }

    public function test_a_revoked_device_cannot_be_reauthorized_by_editing(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->actingAs($owner)->putJson("/api/update-admin/clients/{$client['id']}", ['status' => 'revoked'])->assertOk();
        $this->actingAs($owner)->putJson("/api/update-admin/clients/{$client['id']}", ['status' => 'authorized'])->assertStatus(409);
    }

    public function test_a_different_machine_presenting_the_token_is_refused(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        UpdateClient::findOrFail($client['id'])->update(['machine_fingerprint' => str_repeat('a', 64)]);
        $this->withHeaders($client['headers'])->postJson('/api/updates/client/check', ['app_version' => '1.0.0', 'machine_fingerprint' => str_repeat('b', 64)])->assertForbidden()->assertJsonPath('code', 'device_mismatch');
    }

    public function test_a_device_cannot_see_or_touch_another_devices_update(): void
    {
        $owner = $this->owner();
        $a = $this->enroll($owner);
        $b = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $a);
        $target = $this->check($a)->json('data.update.target_id');

        $this->assertNull($this->check($b)->json('data.update'), 'not assigned to b');
        $this->withHeaders($b['headers'])->getJson("/api/updates/client/targets/{$target}/release")->assertNotFound();
        $this->withHeaders($b['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertNotFound();
        $this->reportStatus($b, $target, 'COMPLETED')->assertNotFound();
    }

    // ------------------------------------------------------------------ targeting
    public function test_all_scope_respects_exclusions_channel_and_later_enrollment(): void
    {
        $owner = $this->owner();
        $included = $this->enroll($owner);
        $excluded = $this->enroll($owner);
        $beta = $this->enroll($owner, 'beta');

        [$release, $packageId] = $this->releaseWithPackage($owner);
        $this->storePayload($packageId);
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertOk();
        $this->actingAs($owner)->postJson('/api/update-admin/deployments', ['release_id' => $release['id'], 'scope' => 'all', 'exclude_client_ids' => [$excluded['id']]])->assertCreated();
        $later = $this->enroll($owner);
        $this->app['auth']->forgetGuards();

        $this->assertSame($this->version, $this->check($included)->json('data.update.version'));
        $this->assertNull($this->check($excluded)->json('data.update'));
        $this->assertNull($this->check($beta)->json('data.update'));
        $this->assertSame($this->version, $this->check($later)->json('data.update.version'));
    }

    public function test_cancelled_deployments_and_unpublished_releases_stop_being_offered(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        [$release] = $this->publishedAndDeployed($owner, $client);
        $this->assertNotNull($this->check($client)->json('data.update'));

        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/unpublish")->assertOk();
        $this->app['auth']->forgetGuards();
        $this->assertNull($this->check($client)->json('data.update'));
    }

    public function test_no_downgrade_offer_even_if_the_device_claims_a_lower_version_after_verification(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner, 'stable', '1.0.0');
        $this->publishedAndDeployed($owner, $client);
        UpdateClient::findOrFail($client['id'])->update(['verified_app_version' => '95.0.0']);
        $this->assertNull($this->check($client, '1.0.0')->json('data.update'), 'server trusts its verified version, not the claim');
        $this->assertTrue($this->check($client, '1.0.0')->json('data.install_unknown'));
    }

    public function test_below_minimum_supported_version_is_blocked(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner, 'stable', '1.0.0');
        [$release] = $this->publishedAndDeployed($owner, $client);
        UpdateRelease::findOrFail($release['id'])->update(['min_supported_version' => '2.0.0']);
        $this->check($client, '1.0.0')->assertOk()->assertJsonPath('data.update', null)->assertJsonPath('data.blocked', 'below_minimum_version');
    }

    public function test_package_choice_incremental_only_from_the_verified_source(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner, 'stable', '1.0.0');
        [$release, $fullId] = $this->releaseWithPackage($owner);
        $this->storePayload($fullId);
        $incId = $this->addPackage($owner, $release['id'], ['package_type' => 'incremental', 'source_version' => '1.0.0', '_payload' => 'small']);
        $this->storePayload($incId, 'small');
        $this->actingAs($owner)->postJson("/api/update-admin/releases/{$release['id']}/publish")->assertOk();
        $this->actingAs($owner)->postJson('/api/update-admin/deployments', ['release_id' => $release['id'], 'scope' => 'selected', 'client_ids' => [$client['id']]])->assertCreated();
        $this->app['auth']->forgetGuards();

        $this->assertSame('incremental', $this->check($client, '1.0.0')->json('data.update.package_type'));
        $this->assertSame('full', $this->check($client, '1.1.0')->json('data.update.package_type'), 'no patch from another version');

        UpdateClient::findOrFail($client['id'])->update(['verified_app_version' => '1.0.0']);
        $this->assertSame('full', $this->check($client, '1.0.5')->json('data.update.package_type'), 'claim disagrees with the verified version: unknown install');

        $target = $this->check($client, '1.0.0')->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertOk();
        $this->assertSame('full', $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/download-token", ['full' => true])->json('data.package_type'), 'a device whose install failed verification asks for full');
    }

    // ------------------------------------------------------------------ download
    public function test_a_download_needs_no_approval_but_installing_does(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');

        $token = $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/download-token")->assertOk()->json('data.token');
        $this->assertNotEmpty($token, 'background download before anyone approved');
        $this->reportStatus($client, $target, 'DOWNLOADING')->assertOk();
        $this->withHeaders($client['headers'])->get("/api/updates/client/download/{$token}")->assertOk();
        $this->reportStatus($client, $target, 'VERIFYING')->assertOk();

        $this->reportStatus($client, $target, 'BACKUP_IN_PROGRESS')->assertStatus(409)->assertJsonPath('code', 'not_approved');
        $this->assertSame('VERIFYING', UpdateDeploymentTarget::find($target)->status, 'downloaded is not permission to install');

        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve', 'source' => 'silent policy'])->assertOk()->assertJsonPath('data.status', 'CLIENT_APPROVED');
        $this->reportStatus($client, $target, 'BACKUP_IN_PROGRESS')->assertOk();
    }

    public function test_approval_before_any_download_still_cannot_jump_to_installing(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertOk();

        $this->reportStatus($client, $target, 'BACKUP_IN_PROGRESS')->assertStatus(409)->assertJsonPath('code', 'no_download');
    }

    public function test_a_live_download_token_is_bound_to_the_device(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $other = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');

        $token = $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/download-token")->assertOk()->json('data.token');
        $this->assertDatabaseMissing('update_download_tokens', ['token_hash' => $token]);

        $this->withHeaders($other['headers'])->get("/api/updates/client/download/{$token}")->assertForbidden();
        $this->flushHeaders();
        $this->get("/api/updates/client/download/{$token}", ['Accept' => 'application/json'])->assertUnauthorized();

        $response = $this->withHeaders($client['headers'])->get("/api/updates/client/download/{$token}", ['Range' => 'bytes=8-12']);
        $this->assertSame(206, $response->getStatusCode(), 'resume uses HTTP Range');
        $this->assertSame('bytes', substr((string) $response->headers->get('Content-Range'), 0, 5));

        \App\Models\UpdateDownloadToken::query()->where('token_hash', hash('sha256', $token))->update(['expires_at' => now()->subSecond()]);
        $this->withHeaders($client['headers'])->get("/api/updates/client/download/{$token}")->assertForbidden();
    }

    public function test_download_token_is_refused_after_rejection(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'reject'])->assertOk()->assertJsonPath('data.decision', 'rejected');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/download-token")->assertStatus(409);
    }

    // ------------------------------------------------------------------ lifecycle
    public function test_completed_cannot_be_reported_out_of_order(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');

        $this->reportStatus($client, $target, 'COMPLETED')->assertStatus(409)->assertJsonPath('code', 'illegal_transition');
        $this->reportStatus($client, $target, 'MIGRATING')->assertStatus(409);
        $this->assertSame('UPDATE_AVAILABLE', UpdateDeploymentTarget::findOrFail($target)->status);
        $this->assertDatabaseHas('update_events', ['target_id' => $target, 'category' => 'security', 'is_error' => true]);
    }

    public function test_verifying_requires_a_recorded_download(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertOk();
        $this->reportStatus($client, $target, 'DOWNLOADING')->assertOk();
        $this->reportStatus($client, $target, 'VERIFYING')->assertStatus(409)->assertJsonPath('code', 'no_download');
    }

    public function test_full_lifecycle_completes_and_sets_the_verified_version(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->walkToHealthCheck($client);

        $this->reportStatus($client, $target, 'COMPLETED', $this->completion($client, $target))->assertOk()->assertJsonPath('data.status', 'COMPLETED');

        $row = UpdateClient::findOrFail($client['id']);
        $this->assertSame($this->version, $row->verified_app_version);
        $this->assertSame(str_repeat('a', 64), $row->verified_schema_fingerprint);
        $this->assertNotNull($row->last_success_at);
        $this->reportStatus($client, $target, 'FAILED')->assertStatus(409);
        $this->assertNull($this->check($client, $this->version)->json('data.update'), 'nothing further to offer');
    }

    #[\PHPUnit\Framework\Attributes\DataProvider('forgedCompletions')]
    public function test_forged_completions_are_refused(array $over): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->walkToHealthCheck($client);

        $this->reportStatus($client, $target, 'COMPLETED', $this->completion($client, $target, $over))->assertStatus(409)->assertJsonPath('code', 'completion_rejected');
        $this->assertSame('HEALTH_CHECK', UpdateDeploymentTarget::findOrFail($target)->status);
        $this->assertNull(UpdateClient::findOrFail($client['id'])->verified_app_version, 'nothing is believed');
    }

    public static function forgedCompletions(): array
    {
        return [
            'wrong version' => [['app_version' => '1.0.1']],
            'wrong manifest' => [['manifest_sha256' => str_repeat('b', 64)]],
            'wrong schema' => [['schema_fingerprint' => str_repeat('c', 64)]],
            'failed health' => [['health' => ['startup' => true, 'database' => false, 'migrations_current' => true, 'schema_compatible' => true]]],
            'no health' => [['health' => []]],
            'bad proof' => [['proof' => str_repeat('d', 64)]],
        ];
    }

    public function test_failure_and_recovery_are_recorded_and_allow_a_retry(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->walkToHealthCheck($client);

        $this->reportStatus($client, $target, 'FAILED', ['message' => 'Migration failed', 'category' => 'migration'])->assertOk();
        $this->assertNotNull(UpdateClient::findOrFail($client['id'])->last_failure_at);
        $this->reportStatus($client, $target, 'RECOVERY_IN_PROGRESS', ['category' => 'recovery'])->assertOk();
        $this->reportStatus($client, $target, 'RECOVERED', ['category' => 'recovery', 'details' => ['restored' => false]])->assertOk();

        $this->assertNull(UpdateClient::findOrFail($client['id'])->verified_app_version, 'a failure proves nothing about the new version');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertOk()->assertJsonPath('data.status', 'CLIENT_APPROVED');

        $monitoring = $this->actingAs($owner)->getJson('/api/update-admin/monitoring?errors_only=1')->assertOk()->json('data');
        $this->assertGreaterThanOrEqual(1, $monitoring['errors_by_category']['migration'] ?? 0);
    }

    public function test_only_a_paired_terminal_may_skip_the_database_steps(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->check($client)->json('data.update.target_id');
        $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/decision", ['decision' => 'approve'])->assertOk();
        $token = $this->withHeaders($client['headers'])->postJson("/api/updates/client/targets/{$target}/download-token")->json('data.token');
        $this->reportStatus($client, $target, 'DOWNLOADING')->assertOk();
        $this->withHeaders($client['headers'])->get("/api/updates/client/download/{$token}")->assertOk();
        $this->reportStatus($client, $target, 'VERIFYING')->assertOk();

        $this->reportStatus($client, $target, 'INSTALLING')->assertStatus(409)->assertJsonPath('code', 'illegal_transition');

        UpdateClient::findOrFail($client['id'])->update(['mode' => 'remote']);
        $this->reportStatus($client, $target, 'INSTALLING')->assertOk();
    }

