    public function test_history_and_deployment_tracking(): void
    {
        $owner = $this->owner();
        $client = $this->enroll($owner);
        $this->publishedAndDeployed($owner, $client);
        $target = $this->walkToHealthCheck($client);
        $this->assertSame($target, $this->withHeaders($client['headers'])->getJson('/api/updates/client/history')->assertOk()->json('data.targets.0.id'));

        $deployment = UpdateDeploymentTarget::findOrFail($target)->deployment_id;
        $detail = $this->actingAs($owner)->getJson("/api/update-admin/deployments/{$deployment}")->assertOk()->json('data');
        $this->assertSame('HEALTH_CHECK', $detail['deployment']['targets'][0]['status']);
        $this->assertNotEmpty($detail['events']);
        $clients = $this->actingAs($owner)->getJson('/api/update-admin/clients')->assertOk()->json('data');
        $mine = collect($clients)->firstWhere('id', $client['id']);
        $this->assertSame(1, $mine['pending_updates']);
        $this->assertArrayNotHasKey('token_hash', $mine);
    }
